       "nodes": [
       {
           "parameters": {},
           "id": "35d05920-ad75-402a-be3c-3277bff7cc67",
           "name": "When clicking ‘Execute workflow’",
           "type": "n8n-nodes-base.manualTrigger",
           "typeVersion": 1,
           "position": [
           880,
           400
           ]
       },
       {
           "parameters": {
           "batchSize": 500,
           "options": {}
           },
           "id": "ae9baa80-4cf9-4848-8953-22e1b7187bf6",
           "name": "Loop Over Items",
           "type": "n8n-nodes-base.splitInBatches",
           "typeVersion": 3,
           "position": [
           1120,
           420
           ]
       },
       {
           "parameters": {
           "resource": "chat",
           "options": {},
           "requestOptions": {}
           },
           "id": "a519f271-82dc-4f60-8cfd-533dec580acc",
           "name": "OpenAI",
           "type": "n8n-nodes-base.openAi",
           "typeVersion": 1,
           "position": [
           1380,
           440
           ]
       },
       {
           "parameters": {
           "unit": "minutes"
           },
           "id": "562d9da3-2142-49bc-9b8f-71b0af42b449",
           "name": "Wait",
           "type": "n8n-nodes-base.wait",
           "typeVersion": 1,
           "position": [
           1620,
           440
           ],
           "webhookId": "714ab157-96d1-448f-b7f5-677882b92b13"
       }
       ],
       "connections": {
       "When clicking ‘Execute workflow’": {
           "main": [
           [
               {
               "node": "Loop Over Items",
               "type": "main",
               "index": 0
               }
           ]
           ]
       },
       "Loop Over Items": {
           "main": [
           null,
           [
               {
               "node": "OpenAI",
               "type": "main",
               "index": 0
               }
           ]
           ]
